import { useCallback, useEffect, useState, type FormEvent } from 'react'; // Manage API data and interactive views.
import { Link } from 'react-router-dom'; // Link visitors to sign-in and registration.
import { BookOpen, ChefHat, Leaf, Refrigerator, Settings, Search, Plus, Clock3, UsersRound, LogOut, X, Archive, Trash2, Pencil, Send, ShieldCheck, CircleUserRound, ArrowLeft } from 'lucide-react'; // Reuse the project's line icon style.

const API = import.meta.env.VITE_API_BASE_URL ?? '/api/v1'; // Use the local Vite proxy by default.
type User = { id: number; email: string; first_name: string; last_name: string | null; is_admin: boolean; email_verified: boolean }; // Describe a signed-in user.
type Category = { id: number; name: string; icon_slug?: string | null }; // Describe a recipe or ingredient category.
type Unit = { id: number; name: string; symbol: string; unit_type: string }; // Describe a measurement unit.
type Conversion = { id: number; from_unit_id: number; to_unit_id: number; factor: number }; // Describe a conversion multiplier.
type Ingredient = { id: number; name: string; image_url: string | null; default_unit_id: number; default_unit_name: string; default_unit_symbol: string; ingredient_category_id: number; ingredient_category_name: string; owner_user_id: number | null; base_ingredient_id: number | null; brand: string | null; calories: number | null; proteins: number | null; carbs: number | null; fats: number | null; nutrition_inherited: boolean; is_archived: boolean }; // Describe a visible ingredient.
type RecipeSummary = { id: number; title: string; description: string | null; prep_time_min: number | null; cook_time_min: number | null; servings: number; image_url: string | null; categories: Category[] }; // Describe one recipe card.
type RecipeDetail = RecipeSummary & { author_id: number; is_public: boolean; ingredients: Array<{ ingredient_id: number; quantity: number; unit_id: number; notes: string | null; ingredient_name: string; unit_symbol: string }>; steps: Array<{ step_number: number; instruction: string }> }; // Describe full recipe information.
type Nutrition = { status: string; servings: number; calories: number | null; proteins: number | null; carbs: number | null; fats: number | null; missing: string[] }; // Describe nutrition values per portion.
type Page = 'discover' | 'mine' | 'ingredients' | 'admin' | 'device' | 'new-recipe'; // Define the app's main sections.
const categoryColor: Record<string, string> = { Dîner: 'coral', Déjeuner: 'lime', 'Petit-déjeuner': 'sun', Dessert: 'pink', Végétarien: 'cyan', Été: 'mango', Entrée: 'violet', Plat: 'blue' }; // Keep category color choices stable.
const colorFor = (name?: string) => categoryColor[name ?? ''] ?? 'mango'; // Give new categories a warm fallback.

async function api<T>(path: string, options: RequestInit = {}): Promise<T> { // Centralize requests and session cookies.
  const response = await fetch(API + path, { credentials: 'include', ...options, headers: { ...(options.body ? { 'Content-Type': 'application/json' } : {}), ...options.headers } }); // Send the user's HttpOnly cookie.
  const body = response.status === 204 ? null : await response.json().catch(() => ({})); // Accept empty and JSON responses.
  if (!response.ok) throw new Error((body as { detail?: string }).detail ?? 'La demande a échoué.'); // Present API errors clearly.
  return body as T; // Return the typed response.
} // Finish the shared request function.

function json(method: string, payload?: unknown): RequestInit { // Build JSON request options.
  return { method, ...(payload === undefined ? {} : { body: JSON.stringify(payload) }) }; // Encode an optional body.
} // Finish the request helper.

export default function App() { // Render the real KitchAI application.
  const [page, setPage] = useState<Page>('discover'); // Track the selected screen.
  const [user, setUser] = useState<User | null>(null); // Track the current user.
  const [recipes, setRecipes] = useState<RecipeSummary[]>([]); // Store public recipe cards.
  const [myRecipes, setMyRecipes] = useState<RecipeSummary[]>([]); // Store this user's recipes.
  const [categories, setCategories] = useState<Category[]>([]); // Store recipe categories.
  const [foodCategories, setFoodCategories] = useState<Category[]>([]); // Store ingredient categories.
  const [units, setUnits] = useState<Unit[]>([]); // Store measurement units.
  const [conversions, setConversions] = useState<Conversion[]>([]); // Store unit conversion rules.
  const [ingredients, setIngredients] = useState<Ingredient[]>([]); // Store visible shared and personal ingredients.
  const [selected, setSelected] = useState<RecipeDetail | null>(null); // Store recipe details opened by the user.
  const [editing, setEditing] = useState<RecipeDetail | null>(null); // Store a recipe currently being edited.
  const [notice, setNotice] = useState(''); // Display success feedback.
  const [error, setError] = useState(''); // Display API failures.
  const [busy, setBusy] = useState(false); // Prevent duplicate writes.

  const refresh = useCallback(async () => { // Load shared data and the current profile.
    const values = await Promise.all([api<{ items: RecipeSummary[] }>('/recipes?page_size=100'), api<Category[]>('/categories/recipes'), api<Category[]>('/categories/ingredients'), api<Unit[]>('/units'), api<Conversion[]>('/unit-conversions'), api<Ingredient[]>('/ingredients')]); // Fetch catalogues together.
    setRecipes(values[0].items); // Show recipes from PostgreSQL.
    setCategories(values[1]); // Store recipe categories.
    setFoodCategories(values[2]); // Store ingredient categories.
    setUnits(values[3]); // Store units.
    setConversions(values[4]); // Store conversions.
    setIngredients(values[5]); // Store visible ingredients.
    const profile = await api<User>('/auth/me').catch(() => null); // Keep public browsing available without a session.
    setUser(profile); // Store the optional account.
    setMyRecipes(profile ? await api<RecipeSummary[]>('/recipes/mine').catch(() => []) : []); // Load private recipes only for their owner.
  }, []); // Keep this loader stable.
  useEffect(() => { void refresh().catch((reason: unknown) => setError(reason instanceof Error ? reason.message : 'Impossible de charger KitchAI.')); }, [refresh]); // Load current application data on entry.

  async function act<T>(operation: () => Promise<T>, success: string): Promise<T | undefined> { // Run a write and refresh the visible data.
    setBusy(true); // Prevent duplicate submissions.
    setError(''); // Clear earlier errors.
    try { const result = await operation(); setNotice(success); await refresh(); return result; } // Save, confirm, and refresh.
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Une erreur est survenue.'); return undefined; } // Show a safe error.
    finally { setBusy(false); } // Restore controls.
  } // Finish shared write handling.
  async function signOut() { // Revoke the current session.
    await api('/auth/logout', json('POST')).catch(() => undefined); // Ask the API to revoke the session.
    setUser(null); setMyRecipes([]); setPage('discover'); setNotice('Tu es déconnecté.'); // Clear private state and return to discovery.
  } // Finish sign-out.
  async function openRecipe(id: number) { // Load a recipe's private or public detail.
    try { setSelected(await api<RecipeDetail>('/recipes/' + id)); } // Store the recipe detail.
    catch (reason) { setError(reason instanceof Error ? reason.message : 'Recette introuvable.'); } // Explain missing or inaccessible recipes.
  } // Finish recipe opening.

  const nav = [{ id: 'discover' as const, label: 'Découvrir', icon: BookOpen }, { id: 'mine' as const, label: 'Mes recettes', icon: ChefHat }, { id: 'ingredients' as const, label: 'Ingrédients', icon: Leaf }, { id: 'device' as const, label: 'Mon écran', icon: Refrigerator }]; // Define regular-user navigation.

  return <div className="app-shell"><aside className="sidebar"><button className="brand brand-button" onClick={() => { setPage('discover'); setSelected(null); }}><span className="brand-mark">K</span><span>Kitch<span className="brand-ai">AI</span></span></button><p className="side-label">MENU</p>{nav.map((item) => <button key={item.id} className={'nav-item ' + (page === item.id ? 'active' : '')} onClick={() => { setPage(item.id); setSelected(null); }}><item.icon size={18} />{item.label}</button>)}{user?.is_admin && <button className={'nav-item ' + (page === 'admin' ? 'active' : '')} onClick={() => { setPage('admin'); setSelected(null); }}><Settings size={18} />Administration</button>}<div className="sidebar-bottom">{user ? <div className="profile"><span className="avatar">{user.first_name.slice(0, 1).toUpperCase()}</span><span>{user.first_name}<small>{user.is_admin ? 'Administrateur' : 'Compte KitchAI'}</small></span><button className="icon-button" onClick={signOut} aria-label="Se déconnecter"><LogOut size={16} /></button></div> : <div className="account-links sidebar-auth"><Link to="/login">Connexion</Link><Link to="/register">Créer un compte</Link></div>}</div></aside><main className="main-content"><header className="topbar"><span className="top-note">RECETTES • INGRÉDIENTS • CUISINE</span><span className="top-account">{user ? user.email + (user.is_admin ? ' · ADMIN' : '') : 'Mode visiteur'}</span></header>{error && <div className="notice notice-error" role="alert">{error}<button onClick={() => setError('')} aria-label="Fermer"><X size={16} /></button></div>}{notice && <div className="notice" role="status">{notice}<button onClick={() => setNotice('')} aria-label="Fermer"><X size={16} /></button></div>}{selected ? <RecipeDetailView recipe={selected} user={user} onClose={() => setSelected(null)} onEdit={() => { setEditing(selected); setSelected(null); setPage('new-recipe'); }} onChanged={(message) => { setSelected(null); setNotice(message); void refresh(); }} /> : page === 'discover' ? <Discover recipes={recipes} categories={categories} onOpen={openRecipe} /> : page === 'mine' ? <MyRecipes recipes={myRecipes} signedIn={Boolean(user)} onOpen={openRecipe} onCreate={() => { setEditing(null); setPage('new-recipe'); }} /> : page === 'ingredients' ? <IngredientsView user={user} ingredients={ingredients} categories={foodCategories} units={units} busy={busy} onSave={(data) => act(() => api('/ingredients', json('POST', data)), 'Ingrédient créé.')} onArchive={(id) => act(() => api('/ingredients/' + id + '/archive', json('POST')), 'Ingrédient archivé.')} onDelete={(id) => act(() => api('/ingredients/' + id, json('DELETE')), 'Ingrédient supprimé.')} /> : page === 'admin' && user?.is_admin ? <AdminView categories={categories} foodCategories={foodCategories} units={units} conversions={conversions} ingredients={ingredients.filter((item) => item.owner_user_id === null)} busy={busy} onSave={(path, data) => act(() => api(path, json('POST', data)), 'Donnée enregistrée.')} onUpdate={(path, data) => act(() => api(path, json('PATCH', data)), 'Donnée modifiée.')} onDelete={(path) => act(() => api(path, { method: 'DELETE' }), 'Donnée supprimée.')} /> : page === 'new-recipe' && user ? <RecipeEditor key={editing?.id ?? 'new'} initial={editing} categories={categories} ingredients={ingredients.filter((item) => !item.is_archived)} units={units} busy={busy} onCancel={() => { setEditing(null); setPage('mine'); }} onSave={(data, id) => act(async () => { const value = await api<RecipeDetail>(id ? '/recipes/' + id : '/recipes', json(id ? 'PUT' : 'POST', data)); setEditing(null); setSelected(value); return value; }, 'Recette enregistrée.')} /> : page === 'device' ? <DevicePreview recipes={myRecipes} onOpen={openRecipe} /> : <SignInNotice />}</main><nav className="mobile-nav">{nav.map((item) => <button key={item.id} className={page === item.id ? 'active' : ''} onClick={() => { setPage(item.id); setSelected(null); }}><item.icon size={18} /><small>{item.label}</small></button>)}</nav></div>; // Keep account and feature navigation responsive.
} // Finish the application component.

// Keep public search tools hidden until the visitor opens the filter panel.
function Discover({ recipes, categories, onOpen }: { recipes: RecipeSummary[]; categories: Category[]; onOpen: (id: number) => void }) { // Render public recipe search and filters.
  const [filtersOpen, setFiltersOpen] = useState(false); // Control the collapsible filter panel.
  const [query, setQuery] = useState(''); // Store title search text.
  const [category, setCategory] = useState('all'); // Store the selected recipe category.
  const [maxTime, setMaxTime] = useState(''); // Store the maximum preparation time.
  const [results, setResults] = useState(recipes); // Show the first public recipes while the API search loads.
  const [total, setTotal] = useState(recipes.length); // Display the complete matching count returned by the API.
  const [page, setPage] = useState(1); // Track public result pages beyond the first twenty recipes.
  const [searchError, setSearchError] = useState(''); // Explain a failed catalogue search.
  useEffect(() => { let cancelled = false; const timer = window.setTimeout(() => { const params = new URLSearchParams({ page: String(page), page_size: '20' }); if (query.trim()) params.set('q', query.trim()); if (category !== 'all') params.set('category_id', category); if (maxTime) params.set('max_prep_time', maxTime); void api<{ items: RecipeSummary[]; total: number }>('/recipes?' + params.toString()).then((result) => { if (!cancelled) { setResults(result.items); setTotal(result.total); setSearchError(''); } }).catch((reason: unknown) => { if (!cancelled) setSearchError(reason instanceof Error ? reason.message : 'Recherche indisponible.'); }); }, 250); return () => { cancelled = true; window.clearTimeout(timer); }; }, [recipes, query, category, maxTime, page]); // Search every public recipe through the API with a short typing delay.
  const activeFilters = Number(Boolean(query.trim())) + Number(category !== 'all') + Number(Boolean(maxTime)); // Show how many criteria are active.
  return <><section className="hero"><div className="hero-copy"><p className="eyebrow"><span className="eyebrow-dot" />LE CARNET DE CUISINE</p><h1>À table,<br /><em>à ta façon.</em></h1><p className="hero-subtitle">Découvre des recettes, garde tes créations privées et cuisine étape par étape.</p></div><div className="hero-art" aria-hidden="true"><div className="art-orbit orbit-one" /><div className="art-orbit orbit-two" /><div className="art-plate"><span>🥬</span><span>🍋</span></div><div className="art-spark spark-one">✳</div><div className="art-spark spark-two">✦</div><div className="art-note">FAIT MAISON <span>✳</span></div></div></section><div className="collection-head"><div><p className="eyebrow">LE CATALOGUE</p><h2>Recettes publiques <span className="recipe-count">{total}</span></h2></div><button type="button" className="filter-button" aria-expanded={filtersOpen} aria-controls="recipe-filters" onClick={() => setFiltersOpen((value) => !value)}><Search size={15} />Filtres{activeFilters > 0 && <span className="filter-count">{activeFilters}</span>}<span aria-hidden="true">{filtersOpen ? '▴' : '▾'}</span></button></div>{filtersOpen && <div id="recipe-filters" className="discover-filters"><label>Rechercher une recette<input type="search" placeholder="Nom de la recette…" value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} /></label><label>Catégorie du repas<select value={category} onChange={(event) => { setCategory(event.target.value); setPage(1); }}><option value="all">Toutes les catégories</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Préparation maximum (minutes)<input type="number" min="0" max="1440" placeholder="Sans limite" value={maxTime} onChange={(event) => { setMaxTime(event.target.value); setPage(1); }} /></label><button type="button" className="auth-secondary" onClick={() => { setQuery(''); setCategory('all'); setMaxTime(''); setPage(1); }}>Effacer les filtres</button></div>}{searchError && <p className="auth-error" role="alert">{searchError}</p>}{results.length ? <section className="recipe-grid">{results.map((recipe) => <RecipeCard key={recipe.id} recipe={recipe} onOpen={() => onOpen(recipe.id)} />)}</section> : <EmptyState title="Aucune recette trouvée" detail="Essaie de modifier les filtres ou reviens plus tard." />}{total > 20 && <div className="form-actions"><button type="button" className="auth-secondary" disabled={page === 1} onClick={() => setPage((value) => value - 1)}>Précédent</button><span className="muted-copy">Page {page} / {Math.ceil(total / 20)}</span><button type="button" className="auth-secondary" disabled={page * 20 >= total} onClick={() => setPage((value) => value + 1)}>Suivant</button></div>}<footer className="footer">FAIT AVEC GOÛT <span>✳</span> KITCHAI</footer></>; // Keep search and filters in one collapsible panel.
} // Finish public discovery.

function RecipeCard({ recipe, onOpen }: { recipe: RecipeSummary; onOpen: () => void }) { // Render one category-colored recipe tile.
  const primary = colorFor(recipe.categories[0]?.name); // Match the tile accent to its first category.
  return <button className={'recipe-card theme-' + primary} onClick={onOpen}><div className={'card-image ' + primary} style={recipe.image_url ? { backgroundImage: 'url(' + recipe.image_url + ')' } : undefined}><div className="card-tags">{recipe.categories.map((item) => <span key={item.id} className={'category-tag tag-' + colorFor(item.name)}>{item.name}</span>)}</div><span className="card-open">↗</span></div><div className="category-stripe">{recipe.categories.map((item) => <span key={item.id} className={'stripe-' + colorFor(item.name)} />)}</div><div className="card-copy"><h3>{recipe.title}</h3><p>{recipe.description || 'Une recette à découvrir.'}</p><div className="card-meta"><span><Clock3 size={14} />{(recipe.prep_time_min ?? 0) + (recipe.cook_time_min ?? 0)} min</span><span><UsersRound size={14} />{recipe.servings} pers.</span><span><Leaf size={14} />{recipe.categories.length} catég.</span></div></div></button>; // Show real recipe information.
} // Finish recipe card.

function MyRecipes({ recipes, signedIn, onOpen, onCreate }: { recipes: RecipeSummary[]; signedIn: boolean; onOpen: (id: number) => void; onCreate: () => void }) { // Render recipes owned by the current account.
  return <section className="data-page"><div className="data-heading"><div><p className="eyebrow">TON CARNET</p><h1>Mes recettes</h1><p className="hero-subtitle">Tes créations restent privées jusqu’à leur publication.</p></div>{signedIn && <button className="primary-button compact" onClick={onCreate}><Plus size={16} />Nouvelle recette</button>}</div>{!signedIn ? <SignInNotice /> : recipes.length ? <section className="recipe-grid">{recipes.map((recipe) => <RecipeCard key={recipe.id} recipe={recipe} onOpen={() => onOpen(recipe.id)} />)}</section> : <EmptyState title="Ton carnet est vide" detail="Crée ta première recette privée." />}</section>; // Keep recipe creation one click away.
} // Finish the personal recipe page.

function IngredientsView({ user, ingredients, categories, units, busy, onSave, onArchive, onDelete }: { user: User | null; ingredients: Ingredient[]; categories: Category[]; units: Unit[]; busy: boolean; onSave: (payload: unknown) => Promise<unknown>; onArchive: (id: number) => Promise<unknown>; onDelete: (id: number) => Promise<unknown> }) { // Render shared and personal ingredient management.
  const [query, setQuery] = useState(''); // Store catalogue search text.
  const [name, setName] = useState(''); // Store the new ingredient name.
  const [categoryId, setCategoryId] = useState(''); // Store the selected category.
  const [unitId, setUnitId] = useState(''); // Store the default unit.
  const [brand, setBrand] = useState(''); // Store an optional brand label.
  const [baseId, setBaseId] = useState(''); // Store an optional shared base ingredient.
  const [calories, setCalories] = useState(''); // Store optional calories per 100 grams.
  const [proteins, setProteins] = useState(''); // Store optional proteins per 100 grams.
  const [carbs, setCarbs] = useState(''); // Store optional carbohydrates per 100 grams.
  const [fats, setFats] = useState(''); // Store optional fats per 100 grams.
  const [visible, setVisible] = useState<Ingredient[]>([]); // Store the current server-filtered ingredient page.
  const [loadingIngredients, setLoadingIngredients] = useState(false); // Show when the catalogue search is running.
  const [hasMoreIngredients, setHasMoreIngredients] = useState(false); // Offer another page when the API returned a full page.
  const [ingredientSearchError, setIngredientSearchError] = useState(''); // Show failures instead of hiding matching foods.
  useEffect(() => { let cancelled = false; const timer = window.setTimeout(() => { setLoadingIngredients(true); void api<Ingredient[]>('/ingredients?q=' + encodeURIComponent(query.trim()) + '&offset=0&limit=30').then((items) => { if (!cancelled) { setVisible(items); setHasMoreIngredients(items.length === 30); setIngredientSearchError(''); } }).catch((reason: unknown) => { if (!cancelled) setIngredientSearchError(reason instanceof Error ? reason.message : 'Recherche indisponible.'); }).finally(() => { if (!cancelled) setLoadingIngredients(false); }); }, 200); return () => { cancelled = true; window.clearTimeout(timer); }; }, [query, ingredients]); // Search every database row and refresh after ingredient changes.
  async function loadMoreIngredients() { setLoadingIngredients(true); try { const next = await api<Ingredient[]>('/ingredients?q=' + encodeURIComponent(query.trim()) + '&offset=' + visible.length + '&limit=30'); setVisible((current) => [...current, ...next]); setHasMoreIngredients(next.length === 30); } catch (reason) { setIngredientSearchError(reason instanceof Error ? reason.message : 'Chargement impossible.'); } finally { setLoadingIngredients(false); } } // Append the next sorted catalogue page.
  async function submit(event: FormEvent<HTMLFormElement>) { // Save a private ingredient owned by the current user.
    event.preventDefault(); // Avoid a full browser reload.
    await onSave({ name, ingredient_category_id: Number(categoryId), default_unit_id: Number(unitId), base_ingredient_id: baseId ? Number(baseId) : null, brand: brand || null, calories: calories ? Number(calories) : null, proteins: proteins ? Number(proteins) : null, carbs: carbs ? Number(carbs) : null, fats: fats ? Number(fats) : null }); // Let the API derive ownership from the session.
    setName(''); setBrand(''); // Clear text values after saving.
  } // Finish ingredient creation.
  return <section className="data-page"><div className="data-heading"><div><p className="eyebrow">CATALOGUE ALIMENTAIRE</p><h1>Ingrédients</h1><p className="hero-subtitle">Catalogue partagé et ingrédients privés dans une seule recherche.</p></div></div><label className="data-search"><Search size={16} /><input placeholder="Chercher un ingrédient…" value={query} onChange={(event) => setQuery(event.target.value)} /></label>{ingredientSearchError && <p className="auth-error" role="alert">{ingredientSearchError}</p>}{user && <form className="data-form" onSubmit={(event) => void submit(event)}><h2>Créer un ingrédient personnel</h2><p className="muted-copy">Valeurs nutritionnelles par 100 g; tu peux compléter celles qui manquent plus tard.</p><div className="form-grid"><label>Nom<input required maxLength={200} value={name} onChange={(event) => setName(event.target.value)} /></label><label>Catégorie<select required value={categoryId} onChange={(event) => setCategoryId(event.target.value)}><option value="">Choisir…</option>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Unité par défaut<select required value={unitId} onChange={(event) => setUnitId(event.target.value)}><option value="">Choisir…</option>{units.map((item) => <option key={item.id} value={item.id}>{item.name} ({item.symbol})</option>)}</select></label><label>Variante de<select value={baseId} onChange={(event) => setBaseId(event.target.value)}><option value="">Aucune</option>{ingredients.filter((item) => item.owner_user_id === null).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Marque<input value={brand} onChange={(event) => setBrand(event.target.value)} /></label><label>Calories / 100 g<input type="number" min="0" step="0.01" value={calories} onChange={(event) => setCalories(event.target.value)} /></label><label>Protéines / 100 g<input type="number" min="0" step="0.01" value={proteins} onChange={(event) => setProteins(event.target.value)} /></label><label>Glucides / 100 g<input type="number" min="0" step="0.01" value={carbs} onChange={(event) => setCarbs(event.target.value)} /></label><label>Lipides / 100 g<input type="number" min="0" step="0.01" value={fats} onChange={(event) => setFats(event.target.value)} /></label></div><button className="primary-button compact" disabled={busy || !categories.length || !units.length}><Plus size={15} />Enregistrer l’ingrédient</button>{(!categories.length || !units.length) && <p className="auth-error">L’admin doit configurer une catégorie et une unité.</p>}</form>}{loadingIngredients && !visible.length && <p className="muted-copy">Recherche des ingrédients…</p>}{visible.length ? <><div className="ingredient-list">{visible.map((item) => <article key={item.id} className="ingredient-row"><div className="ingredient-avatar"><Leaf size={17} /></div><div className="ingredient-copy"><strong>{item.name}{item.brand ? ' · ' + item.brand : ''}</strong><small>{item.ingredient_category_name} · {item.default_unit_symbol} · {item.owner_user_id === null ? 'catalogue partagé' : 'personnel'}</small></div><div className="nutrition-mini"><span>{item.calories ?? '—'} kcal</span><span>{item.proteins ?? '—'} g prot.</span></div>{user && item.owner_user_id === user.id && <div className="row-actions"><button className="icon-button" onClick={() => void onArchive(item.id)} aria-label="Archiver"><Archive size={16} /></button><button className="icon-button danger" onClick={() => window.confirm('Supprimer cet ingrédient ?') && void onDelete(item.id)} aria-label="Supprimer"><Trash2 size={16} /></button></div>}</article>)}</div>{hasMoreIngredients && <button className="auth-secondary" disabled={loadingIngredients} onClick={() => void loadMoreIngredients()}>{loadingIngredients ? "Chargement…" : "Afficher plus d’ingrédients"}</button>}</> : !loadingIngredients && <EmptyState title="Aucun ingrédient trouvé" detail="Essaie un autre nom ou crée ton ingrédient personnel." />}</section>; // Search all catalogue pages on the server.
} // Finish ingredient catalogue.

function EmptyState({ title, detail }: { title: string; detail: string }) { // Explain why a catalogue section is empty.
  return <div className="empty-state"><ChefHat size={25} /><h2>{title}</h2><p>{detail}</p></div>; // Keep empty pages useful.
} // Finish empty state.

function SignInNotice() { // Direct visitors to sign in before private actions.
  return <div className="empty-state"><CircleUserRound size={25} /><h2>Connecte-toi pour continuer</h2><p>Un compte est nécessaire pour gérer tes recettes et ingrédients.</p><Link className="primary-button compact" to="/login">Se connecter</Link></div>; // Link to the authentication screen.
} // Finish sign-in guidance.

function AdminView({ categories, foodCategories, units, conversions, ingredients, busy, onSave, onUpdate, onDelete }: { categories: Category[]; foodCategories: Category[]; units: Unit[]; conversions: Conversion[]; ingredients: Ingredient[]; busy: boolean; onSave: (path: string, payload: unknown) => Promise<unknown>; onUpdate: (path: string, payload: unknown) => Promise<unknown>; onDelete: (path: string) => Promise<unknown> }) { // Manage admin-controlled shared references.
  const [baseQuery, setBaseQuery] = useState(''); // Search shared ingredients without rendering the entire Ciqual catalogue.
  const [editingBase, setEditingBase] = useState<Ingredient | null>(null); // Open a focused editor for the selected base ingredient.
  const [mealName, setMealName] = useState(''); const [foodName, setFoodName] = useState(''); const [unitName, setUnitName] = useState(''); const [symbol, setSymbol] = useState(''); const [unitType, setUnitType] = useState('mass'); const [from, setFrom] = useState(''); const [to, setTo] = useState(''); const [factor, setFactor] = useState(''); const [baseName, setBaseName] = useState(''); const [baseCategory, setBaseCategory] = useState(''); const [baseUnit, setBaseUnit] = useState(''); // Store current form entries.
  async function save(event: FormEvent<HTMLFormElement>, path: string, payload: unknown, clear: () => void) { event.preventDefault(); await onSave(path, payload); clear(); } // Save one admin form and clear it.
  function remove(path: string, label: string) { if (window.confirm('Supprimer ' + label + ' ?')) void onDelete(path); } // Confirm a reference deletion before calling the API.
  return <section className="data-page"><div className="data-heading"><div><p className="eyebrow">ESPACE SÉCURISÉ</p><h1>Administration</h1><p className="hero-subtitle">Gère les références partagées du catalogue.</p></div><span className="admin-mark"><ShieldCheck size={18} />ADMIN</span></div><div className="admin-grid"><form className="data-form" onSubmit={(event) => void save(event, '/admin/categories/recipes', { name: mealName.trim() }, () => setMealName(''))}><h2>Catégories de recettes</h2><label>Nouvelle catégorie<input required value={mealName} onChange={(event) => setMealName(event.target.value)} /></label><button className="primary-button compact" disabled={busy}><Plus size={15} />Ajouter</button><div className="admin-list">{categories.map((item) => <div className="admin-row" key={item.id}><button type="button" className="admin-row-edit" onClick={() => { const name = window.prompt('Nouveau nom de catégorie', item.name); if (name?.trim()) void onUpdate('/admin/categories/recipes/' + item.id, { name: name.trim() }); }}>{item.name}<Pencil size={13} /></button><button type="button" className="icon-button danger" disabled={busy} onClick={() => remove('/admin/categories/recipes/' + item.id, 'la catégorie « ' + item.name + ' »')} aria-label={'Supprimer ' + item.name}><Trash2 size={14} /></button></div>)}</div></form><form className="data-form" onSubmit={(event) => void save(event, '/admin/categories/ingredients', { name: foodName.trim() }, () => setFoodName(''))}><h2>Catégories d’ingrédients</h2><label>Nouvelle catégorie<input required value={foodName} onChange={(event) => setFoodName(event.target.value)} /></label><button className="primary-button compact" disabled={busy}><Plus size={15} />Ajouter</button><div className="admin-list">{foodCategories.map((item) => <div className="admin-row" key={item.id}><span>{item.name}</span><button type="button" className="icon-button danger" disabled={busy} onClick={() => remove('/admin/categories/ingredients/' + item.id, 'la catégorie « ' + item.name + ' »')} aria-label={'Supprimer ' + item.name}><Trash2 size={14} /></button></div>)}</div></form><form className="data-form" onSubmit={(event) => void save(event, '/admin/units', { name: unitName.trim(), symbol: symbol.trim(), unit_type: unitType }, () => { setUnitName(''); setSymbol(''); })}><h2>Unités</h2><div className="form-grid"><label>Nom<input required value={unitName} onChange={(event) => setUnitName(event.target.value)} /></label><label>Symbole<input required value={symbol} onChange={(event) => setSymbol(event.target.value)} /></label><label>Type<select value={unitType} onChange={(event) => setUnitType(event.target.value)}><option value="mass">Masse</option><option value="volume">Volume</option><option value="count">Unité</option></select></label></div><button className="primary-button compact" disabled={busy}><Plus size={15} />Ajouter</button><div className="admin-list">{units.map((item) => <div className="admin-row" key={item.id}><button type="button" className="admin-row-edit" onClick={() => { const name = window.prompt('Nouveau nom', item.name); if (name?.trim()) void onUpdate('/admin/units/' + item.id, { id: item.id, name: name.trim(), symbol: item.symbol, unit_type: item.unit_type }); }}>{item.name} ({item.symbol})<Pencil size={13} /></button><button type="button" className="icon-button danger" disabled={busy} onClick={() => remove('/admin/units/' + item.id, 'l’unité « ' + item.name + ' »')} aria-label={'Supprimer ' + item.name}><Trash2 size={14} /></button></div>)}</div></form><form className="data-form" onSubmit={(event) => void save(event, '/admin/unit-conversions', { from_unit_id: Number(from), to_unit_id: Number(to), factor: Number(factor) }, () => setFactor(''))}><h2>Conversions</h2><div className="form-grid"><label>De<select required value={from} onChange={(event) => setFrom(event.target.value)}><option value="">Choisir…</option>{units.map((unit) => <option key={unit.id} value={unit.id}>{unit.name} ({unit.symbol})</option>)}</select></label><label>Vers<select required value={to} onChange={(event) => setTo(event.target.value)}><option value="">Choisir…</option>{units.map((unit) => <option key={unit.id} value={unit.id}>{unit.name} ({unit.symbol})</option>)}</select></label><label>Multiplicateur<input required type="number" min="0.000001" step="any" value={factor} onChange={(event) => setFactor(event.target.value)} /></label></div><p className="muted-copy">Quantité de départ × multiplicateur = quantité d’arrivée.</p><button className="primary-button compact" disabled={busy}><Plus size={15} />Ajouter</button><div className="admin-list">{conversions.map((item) => <div className="admin-row" key={item.id}><span>{units.find((unit) => unit.id === item.from_unit_id)?.symbol} × {item.factor} → {units.find((unit) => unit.id === item.to_unit_id)?.symbol}</span><button type="button" className="icon-button danger" disabled={busy} onClick={() => remove('/admin/unit-conversions/' + item.id, 'cette conversion')} aria-label="Supprimer cette conversion"><Trash2 size={14} /></button></div>)}</div></form><form className="data-form" onSubmit={(event) => void save(event, '/admin/ingredients', { name: baseName.trim(), ingredient_category_id: Number(baseCategory), default_unit_id: Number(baseUnit) }, () => setBaseName(''))}><h2>Ingrédient partagé</h2><label>Nom<input required value={baseName} onChange={(event) => setBaseName(event.target.value)} /></label><label>Catégorie<select required value={baseCategory} onChange={(event) => setBaseCategory(event.target.value)}><option value="">Choisir…</option>{foodCategories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Unité<select required value={baseUnit} onChange={(event) => setBaseUnit(event.target.value)}><option value="">Choisir…</option>{units.map((unit) => <option key={unit.id} value={unit.id}>{unit.name} ({unit.symbol})</option>)}</select></label><button className="primary-button compact" disabled={busy || !foodCategories.length || !units.length}><Plus size={15} />Ajouter l’aliment</button><p className="muted-copy">{ingredients.length} aliments partagés dont Ciqual.</p><label>Modifier un ingrédient partagé<input type="search" placeholder="Chercher par nom…" value={baseQuery} onChange={(event) => setBaseQuery(event.target.value)} /></label><div className="admin-list">{baseQuery.trim().length >= 2 && ingredients.filter((item) => item.name.toLocaleLowerCase('fr').includes(baseQuery.trim().toLocaleLowerCase('fr'))).slice(0, 25).map((item) => <button type="button" key={item.id} onClick={() => setEditingBase(item)}>{item.name}<Pencil size={13} /></button>)}</div></form></div>{editingBase && <SharedIngredientEditor key={editingBase.id} ingredient={editingBase} categories={foodCategories} units={units} busy={busy} onUpdate={onUpdate} onClose={() => setEditingBase(null)} />}</section>; // Keep each shared data type in its own panel.
} // Finish admin controls.

// Edit one shared catalogue entry with the fields administrators correct most often.
function SharedIngredientEditor({ ingredient, categories, units, busy, onUpdate, onClose }: { ingredient: Ingredient; categories: Category[]; units: Unit[]; busy: boolean; onUpdate: (path: string, payload: unknown) => Promise<unknown>; onClose: () => void }) { // Provide a focused base-ingredient form.
  const [name, setName] = useState(ingredient.name); // Edit the ingredient display name.
  const [categoryId, setCategoryId] = useState(String(ingredient.ingredient_category_id)); // Edit the food category.
  const [unitId, setUnitId] = useState(String(ingredient.default_unit_id)); // Edit the default measurement unit.
  const [calories, setCalories] = useState(String(ingredient.calories ?? '')); // Edit kcal per 100 grams.
  const [proteins, setProteins] = useState(String(ingredient.proteins ?? '')); // Edit protein grams per 100 grams.
  const [carbs, setCarbs] = useState(String(ingredient.carbs ?? '')); // Edit carbohydrate grams per 100 grams.
  const [fats, setFats] = useState(String(ingredient.fats ?? '')); // Edit fat grams per 100 grams.
  async function save(event: FormEvent<HTMLFormElement>) { event.preventDefault(); const saved = await onUpdate('/admin/ingredients/' + ingredient.id, { name: name.trim(), ingredient_category_id: Number(categoryId), default_unit_id: Number(unitId), calories: calories === '' ? null : Number(calories), proteins: proteins === '' ? null : Number(proteins), carbs: carbs === '' ? null : Number(carbs), fats: fats === '' ? null : Number(fats) }); if (saved) onClose(); } // Save validated changes through the admin API.
  return <form className="data-form shared-ingredient-editor" onSubmit={(event) => void save(event)}><h2>Modifier « {ingredient.name} »</h2><p className="muted-copy">Valeurs nutritionnelles pour 100 g.</p><div className="form-grid"><label>Nom<input required value={name} onChange={(event) => setName(event.target.value)} /></label><label>Catégorie<select required value={categoryId} onChange={(event) => setCategoryId(event.target.value)}>{categories.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label>Unité par défaut<select required value={unitId} onChange={(event) => setUnitId(event.target.value)}>{units.map((item) => <option key={item.id} value={item.id}>{item.name} ({item.symbol})</option>)}</select></label><label>Calories<input type="number" min="0" step="any" value={calories} onChange={(event) => setCalories(event.target.value)} /></label><label>Protéines<input type="number" min="0" step="any" value={proteins} onChange={(event) => setProteins(event.target.value)} /></label><label>Glucides<input type="number" min="0" step="any" value={carbs} onChange={(event) => setCarbs(event.target.value)} /></label><label>Lipides<input type="number" min="0" step="any" value={fats} onChange={(event) => setFats(event.target.value)} /></label></div><div className="form-actions"><button className="primary-button compact" disabled={busy}>Enregistrer les modifications</button><button type="button" className="auth-secondary" onClick={onClose}>Annuler</button></div></form>; // Keep catalogue corrections accessible from the admin page.
} // Finish shared ingredient editing.

// Search the ingredient catalogue without opening a thousands-item native select.
function IngredientCombobox({ ingredients, selectedId, onSelect }: { ingredients: Ingredient[]; selectedId: string; onSelect: (item: Ingredient | null) => void }) { // Select one ingredient through server-filtered suggestions.
  const [text, setText] = useState(ingredients.find((item) => String(item.id) === selectedId)?.name ?? ''); // Show the current ingredient label when editing.
  const [open, setOpen] = useState(false); // Hide suggestions until the user types at least two letters.
  const [active, setActive] = useState(0); // Track the keyboard-highlighted suggestion.
  const [matches, setMatches] = useState<Ingredient[]>([]); // Store only ingredients returned by the server-side search.
  const [searching, setSearching] = useState(false); // Show when the catalogue search is still running.
  useEffect(() => { let cancelled = false; const query = text.trim(); if (query.length < 2) { setMatches([]); setSearching(false); return () => { cancelled = true; }; } setSearching(true); const timer = window.setTimeout(() => { void api<Ingredient[]>('/ingredients/search?q=' + encodeURIComponent(query)).then((items) => { if (!cancelled) setMatches(items); }).catch(() => { if (!cancelled) setMatches([]); }).finally(() => { if (!cancelled) setSearching(false); }); }, 180); return () => { cancelled = true; window.clearTimeout(timer); }; }, [text]); // Search the complete catalogue after a short typing pause.
  function choose(item: Ingredient) { setText(item.name); onSelect(item); setOpen(false); } // Store the selected ingredient and its default unit.
  function change(value: string) { setText(value); onSelect(null); setActive(0); setOpen(value.trim().length >= 2); } // Clear the prior selection when the query changes.
  function handleKey(event: React.KeyboardEvent<HTMLInputElement>) { if (event.key === 'Escape') setOpen(false); if (event.key === 'ArrowDown') { event.preventDefault(); setActive((value) => Math.min(value + 1, matches.length - 1)); } if (event.key === 'ArrowUp') { event.preventDefault(); setActive((value) => Math.max(value - 1, 0)); } if (event.key === 'Enter' && open && matches[active]) { event.preventDefault(); choose(matches[active]); } } // Support keyboard navigation without submitting the recipe.
  return <div className="ingredient-combobox"><input role="combobox" aria-autocomplete="list" aria-expanded={open} required placeholder="Chercher un ingrédient…" value={text} onChange={(event) => change(event.target.value)} onFocus={() => setOpen(text.trim().length >= 2)} onBlur={() => setOpen(false)} onKeyDown={handleKey} />{open && <div className="ingredient-suggestions" role="listbox">{searching ? <p>Recherche dans le catalogue…</p> : matches.length ? matches.map((item, index) => <button type="button" role="option" aria-selected={index === active} className={index === active ? 'active' : ''} key={item.id} onMouseDown={(event) => event.preventDefault()} onClick={() => choose(item)}>{item.name}{item.brand ? ' · ' + item.brand : ''}</button>) : <p>Aucun ingrédient correspondant.</p>}</div>}</div>; // Keep the full catalogue hidden until a search produces suggestions.
} // Finish the searchable ingredient control.

function RecipeEditor({ initial, categories, ingredients, units, busy, onCancel, onSave }: { initial: RecipeDetail | null; categories: Category[]; ingredients: Ingredient[]; units: Unit[]; busy: boolean; onCancel: () => void; onSave: (payload: unknown, id?: number) => Promise<unknown> }) { // Create or edit one recipe.
  const [title, setTitle] = useState(initial?.title ?? ''); const [description, setDescription] = useState(initial?.description ?? ''); const [prep, setPrep] = useState(initial?.prep_time_min?.toString() ?? ''); const [cook, setCook] = useState(initial?.cook_time_min?.toString() ?? ''); const [servings, setServings] = useState(String(initial?.servings ?? 4)); const [imageUrl, setImageUrl] = useState(initial?.image_url ?? ''); const [categoryIds, setCategoryIds] = useState<number[]>(initial?.categories.map((item) => item.id) ?? []); const [rows, setRows] = useState<Array<{ ingredient_id: string; quantity: string; unit_id: string }>>(initial?.ingredients.map((item) => ({ ingredient_id: String(item.ingredient_id), quantity: String(item.quantity), unit_id: String(item.unit_id) })) ?? []); const [steps, setSteps] = useState(initial?.steps.map((item) => item.instruction).join('\n') ?? ''); const [formError, setFormError] = useState(''); // Initialize fields and validate ingredient selection.
  const [uploading, setUploading] = useState(false); // Track whether the cover image is uploading.
  const [uploadError, setUploadError] = useState(''); // Show a useful message if image upload fails.
  function updateRow(index: number, key: 'ingredient_id' | 'quantity' | 'unit_id', value: string, defaultUnitId?: number) { setRows((current) => current.map((row, rowIndex) => rowIndex === index ? { ...row, [key]: value, ...(key === 'ingredient_id' ? { unit_id: defaultUnitId?.toString() ?? ingredients.find((item) => String(item.id) === value)?.default_unit_id.toString() ?? '' } : {}) } : row)); } // Select a default unit with each ingredient.
  async function uploadCover(file: File) { // Upload one selected recipe cover to the local API.
    setUploading(true); setUploadError(''); // Reset progress and earlier errors.
    try { const response = await fetch(API + '/media/recipe-covers', { method: 'POST', credentials: 'include', headers: { 'Content-Type': file.type }, body: file }); const result = await response.json(); if (!response.ok) throw new Error(result.detail ?? 'Téléversement impossible.'); setImageUrl(result.image_url); } // Keep the returned same-origin URL on the recipe form.
    catch (reason) { setUploadError(reason instanceof Error ? reason.message : 'Téléversement impossible.'); } // Explain rejected files.
    finally { setUploading(false); } // Restore the file control.
  } // Finish cover upload handling.
  async function submit(event: FormEvent<HTMLFormElement>) { event.preventDefault(); if (rows.some((row) => !row.ingredient_id || !row.quantity || !row.unit_id)) { setFormError('Choisis une proposition pour chaque ingrédient et complète sa quantité et son unité.'); return; } setFormError(''); const data = { title, description: description || null, prep_time_min: prep ? Number(prep) : null, cook_time_min: cook ? Number(cook) : null, servings: Number(servings), image_url: imageUrl || null, category_ids: categoryIds, ingredients: rows.filter((row) => row.ingredient_id && row.quantity && row.unit_id).map((row) => ({ ingredient_id: Number(row.ingredient_id), quantity: Number(row.quantity), unit_id: Number(row.unit_id) })), steps: steps.split(/\r?\n/).map((step) => step.trim()).filter(Boolean).map((instruction) => ({ instruction })) }; await onSave(data, initial?.id); } // Convert form values into the API request.
  return <section className="data-page"><button className="back-button" onClick={onCancel}><ArrowLeft size={16} />Mes recettes</button><div className="data-heading"><div><p className="eyebrow">NOUVELLE CRÉATION</p><h1>{initial ? 'Modifier une recette' : 'Créer une recette'}</h1><p className="hero-subtitle">La recette reste privée jusqu’à sa publication.</p></div></div><form className="data-form recipe-editor" onSubmit={(event) => void submit(event)}><div className="form-grid"><label>Titre<input required maxLength={200} value={title} onChange={(event) => setTitle(event.target.value)} /></label><label>Portions<input type="number" min="1" max="100" required value={servings} onChange={(event) => setServings(event.target.value)} /></label><label>Préparation (min)<input type="number" min="0" value={prep} onChange={(event) => setPrep(event.target.value)} /></label><label>Cuisson (min)<input type="number" min="0" value={cook} onChange={(event) => setCook(event.target.value)} /></label></div><label>Description<textarea rows={3} value={description} onChange={(event) => setDescription(event.target.value)} /></label><label>Importer une photo (JPEG, PNG, WebP — 5 Mo max)<input type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => { const file = event.target.files?.[0]; if (file) void uploadCover(file); }} /></label>{uploading && <p className="muted-copy">Téléversement de la photo…</p>}{uploadError && <p className="auth-error">{uploadError}</p>}<label>Ou URL de couverture<input type="url" value={imageUrl} onChange={(event) => setImageUrl(event.target.value)} placeholder="https://…" /></label><fieldset><legend>Catégories</legend><div className="checkbox-list">{categories.map((item) => <label key={item.id}><input type="checkbox" checked={categoryIds.includes(item.id)} onChange={(event) => setCategoryIds((ids) => event.target.checked ? [...ids, item.id] : ids.filter((id) => id !== item.id))} />{item.name}</label>)}</div></fieldset><h2>Ingrédients</h2>{formError && <p className="auth-error" role="alert">{formError}</p>}{rows.map((row, index) => <div className="ingredient-editor-row" key={index}><IngredientCombobox ingredients={ingredients} selectedId={row.ingredient_id} onSelect={(item) => updateRow(index, 'ingredient_id', item ? String(item.id) : '', item?.default_unit_id)} /><input required type="number" min="0.0001" step="any" value={row.quantity} onChange={(event) => updateRow(index, 'quantity', event.target.value)} /><select required value={row.unit_id} onChange={(event) => updateRow(index, 'unit_id', event.target.value)}><option value="">Unité…</option>{units.map((unit) => <option key={unit.id} value={unit.id}>{unit.symbol}</option>)}</select><button className="icon-button" type="button" onClick={() => setRows((current) => current.filter((_, rowIndex) => rowIndex !== index))} aria-label="Retirer"><X size={15} /></button></div>)}<button className="auth-secondary" type="button" onClick={() => setRows((current) => [...current, { ingredient_id: '', quantity: '1', unit_id: '' }])}><Plus size={14} />Ajouter un ingrédient</button><label>Étapes — une par ligne<textarea rows={7} value={steps} onChange={(event) => setSteps(event.target.value)} placeholder="Une instruction par ligne…" /></label><div className="form-actions"><button className="primary-button compact" disabled={busy || uploading}><Plus size={15} />Enregistrer en privé</button><button className="auth-secondary" type="button" onClick={onCancel}>Annuler</button></div></form></section>; // Keep all recipe fields in one responsive form.
} // Finish recipe editor.

function RecipeDetailView({ recipe, user, onClose, onEdit, onChanged }: { recipe: RecipeDetail; user: User | null; onClose: () => void; onEdit: () => void; onChanged: (message: string) => void }) { // Show ingredients, ordered steps, nutrition, and owner controls.
  const [nutrition, setNutrition] = useState<Nutrition | null>(null); const [error, setError] = useState(''); const owner = user?.id === recipe.author_id; // Track nutrition and author permissions.
  useEffect(() => { void api<Nutrition>('/recipes/' + recipe.id + '/nutrition').then(setNutrition).catch((reason: unknown) => setError(reason instanceof Error ? reason.message : 'Nutrition indisponible.')); }, [recipe.id]); // Load per-serving nutrition.
  async function change(path: string, method: string, message: string) { try { await api(path, json(method)); onChanged(message); } catch (reason) { setError(reason instanceof Error ? reason.message : 'Action impossible.'); } } // Run publish or moderation actions.
  return <section className="data-page"><button className="back-button" onClick={onClose}><ArrowLeft size={16} />Retour</button><article className="recipe-detail"><div className="detail-cover" style={recipe.image_url ? { backgroundImage: 'url(' + recipe.image_url + ')' } : undefined}><div className="card-tags">{recipe.categories.map((item) => <span key={item.id} className={'category-tag tag-' + colorFor(item.name)}>{item.name}</span>)}</div></div><div className="detail-body"><p className="eyebrow">{recipe.is_public ? 'RECETTE PUBLIQUE' : 'RECETTE PRIVÉE'} · {recipe.prep_time_min ?? 0} MIN</p><h1>{recipe.title}</h1><p className="hero-subtitle">{recipe.description}</p><div className="detail-metrics"><span><Clock3 size={16} />{(recipe.prep_time_min ?? 0) + (recipe.cook_time_min ?? 0)} min</span><span><UsersRound size={16} />{recipe.servings} portions</span></div>{error && <p className="auth-error">{error}</p>}<div className="nutrition-card"><h2>Nutrition par portion</h2>{nutrition?.status === 'complete' ? <div className="nutrition-grid"><span>{Number(nutrition.calories).toFixed(0)}<small>kcal</small></span><span>{Number(nutrition.proteins).toFixed(1)} g<small>protéines</small></span><span>{Number(nutrition.carbs).toFixed(1)} g<small>glucides</small></span><span>{Number(nutrition.fats).toFixed(1)} g<small>lipides</small></span></div> : <p>{nutrition?.missing.join(' ') ?? 'Calcul en cours…'}</p>}</div><div className="detail-columns"><section><h2>Ingrédients</h2><ul className="detail-list">{recipe.ingredients.map((item, index) => <li key={index}><strong>{item.quantity} {item.unit_symbol}</strong> {item.ingredient_name}</li>)}</ul></section><section><h2>Étapes</h2><ol className="detail-list steps-list">{recipe.steps.map((item) => <li key={item.step_number}>{item.instruction}</li>)}</ol></section></div>{(owner || user?.is_admin) && <div className="form-actions">{owner && <button className="primary-button compact" onClick={onEdit}><Pencil size={14} />Modifier</button>}{owner && <button className="auth-secondary" onClick={() => void change('/recipes/' + recipe.id + (recipe.is_public ? '/unpublish' : '/publish'), 'POST', recipe.is_public ? 'Recette rendue privée.' : 'Recette publiée.')}>{recipe.is_public ? 'Dépublier' : 'Publier'}</button>}{user?.is_admin && recipe.is_public && <button className="auth-secondary" onClick={() => void change('/admin/recipes/' + recipe.id + '/hide', 'POST', 'Recette masquée.')}>Masquer</button>}{(owner || user?.is_admin) && <button className="auth-secondary danger-text" onClick={() => window.confirm('Supprimer cette recette ?') && void change('/recipes/' + recipe.id, 'DELETE', 'Recette supprimée.')}>Supprimer</button>}</div>}</div></article></section>; // Keep controls restricted to the author and administrator.
} // Finish recipe detail.
function DevicePreview({ recipes, onOpen }: { recipes: RecipeSummary[]; onOpen: (id: number) => void }) { // Preview recipe content on a cooking screen.
  const [selected, setSelected] = useState<RecipeSummary | null>(null); const [details, setDetails] = useState<RecipeDetail | null>(null); const [step, setStep] = useState(0); // Track the preview recipe and current instruction.
  useEffect(() => { if (selected) void api<RecipeDetail>('/recipes/' + selected.id).then((value) => { setDetails(value); setStep(0); }).catch(() => setDetails(null)); }, [selected]); // Load the chosen recipe details.
  return <section className="data-page"><div className="data-heading"><div><p className="eyebrow">ÉCRAN DE CUISINE</p><h1>Mon écran</h1><p className="hero-subtitle">Aperçu de la navigation entre les étapes.</p></div></div><div className="device-preview"><div className="device-top"><span>KITCHAI COOK</span><span>APERÇU LOCAL</span></div><div className="device-screen">{details ? <><p className="eyebrow">{details.title}</p><h2>{details.steps.length ? 'Étape ' + (step + 1) + ' / ' + details.steps.length : 'Ingrédients'}</h2><p>{details.steps[step]?.instruction ?? details.ingredients.map((item) => item.quantity + ' ' + item.unit_symbol + ' ' + item.ingredient_name).join(' · ')}</p><div className="device-controls"><button className="auth-secondary" disabled={step === 0} onClick={() => setStep((value) => Math.max(0, value - 1))}>Précédent</button><button className="primary-button compact" disabled={step >= details.steps.length - 1} onClick={() => setStep((value) => Math.min(details.steps.length - 1, value + 1))}>Suivant</button></div><button className="auth-secondary" onClick={() => onOpen(details.id)}>Ouvrir la fiche</button></> : <><Refrigerator size={32} /><h2>{selected ? 'Chargement…' : 'Aucune recette choisie'}</h2><p>Choisis une de tes recettes pour voir les étapes.</p></>}</div></div><div className="device-recipe-list">{recipes.map((item) => <button key={item.id} className="nav-item" onClick={() => setSelected(item)}><ChefHat size={16} />{item.title}<Send size={14} /></button>)}</div><p className="muted-copy">Aperçu logiciel seulement; le jumelage au Raspberry physique reste à réaliser.</p></section>; // Show a local cooking preview without claiming hardware is connected.
} // Finish the preview screen.

